"""Build docs/demo.html (Ukrainian) and docs/demo-ru.html (Russian) from the graph, prices and bench results.
Usage: uv run python docs/src/build_demo.py   (published copies: see README)"""
import asyncio
import json
from collections import Counter
from pathlib import Path

from mcp.client import Client

from nwt_mcp.cards import Graph, dumps, tokens
from nwt_mcp.schema import RELS, TYPES
from nwt_mcp.server import mcp

HERE = Path(__file__).resolve().parent
DOCS, ROOT = HERE.parent, HERE.parents[1]
EXAMPLES = {"feedstock": "PLX-FEED-CRUDE", "intermediate": "PLX-INT-NAPHTHA", "monomer": "PLX-MON-ETHYLENE", "polymer": "PLX-POL-PE",
            "variety": "PLX-VAR-HDPE", "substance": "PLX-SUB-MIXED-XYLENES", "collection": "col:CMD", "category": "cat:CMD/PET",
            "subcategory": "sub:CMD/PET/PLA-PE", "symbol": "sym:CMD/PET/PLA-PE/HDPE_FILM", "family": "fam:nwt-cmd-pet-pla-pe-pricing",
            "field": "fld:price_mid", "data_domain": "dom:pricing", "field_category": "fcat:identifier"}


def data():
    g = Graph()
    edges = Counter((g.nodes[s][0], r, g.nodes[d][0]) for s, outs in g.out.items() for r, d in outs)
    types = {t: {"count": g.type_counts[t], "card": g.type_card(t), "card_tok": tokens(g.type_card(t)), "example": g.node(EXAMPLES[t]),
                 "example_tok": tokens(g.node(EXAMPLES[t])), "what": TYPES[t][3], "layer": TYPES[t][0]} for t in TYPES}
    steps = [("nwt_map", {}, g.map()), ("nwt_search", {"q": "hdpe film"}, g.search("hdpe film")), ("nwt_get", {"id": "type:variety"}, g.type_card("variety")),
             ("nwt_get", {"id": "PLX-VAR-HDPE"}, g.node("PLX-VAR-HDPE")), ("nwt_prices", {"id": "PLX-VAR-HDPE"}, g.prices("PLX-VAR-HDPE")),
             ("nwt_walk", {"id": "PLX-VAR-HDPE", "direction": "up", "depth": 6}, g.walk("PLX-VAR-HDPE", "up", depth=6))]

    async def defs():
        async with Client(mcp) as c:
            tl = (await c.list_tools()).tools
            return tokens(json.dumps([t.model_dump(exclude_none=True) for t in tl])), tokens(c.instructions or "")

    dtok, itok = asyncio.run(defs())
    fam_own = sum(len({d for r, d in g.out[i] if r == "has_field"} - g.base_fields - g.domain_fields.get(g.domain_of(i), set()))
                  for i, n in g.nodes.items() if n[0] == "family")
    res = {t: [json.loads(l) for l in (ROOT / f"bench/results/{t}.jsonl").read_text().splitlines()] for t in ("main", "v3")}
    v3 = res["v3"]
    bench = {"ok": sum(r["ok"] for r in v3), "errors": sum(len(r["tool_errors"]) for r in v3), "errors_v1": sum(len(r["tool_errors"]) for r in res["main"]),
             "haiku_session": sum(r["cost"] or 0 for r in v3 if r["model"] == "haiku") / 50,
             "sonnet_session": sum(r["cost"] or 0 for r in v3 if r["model"] == "sonnet") / 50}
    return {"version": g.version, "edges": [[a, r, b, n, RELS[r][0]] for (a, r, b), n in sorted(edges.items())], "types": types,
            "steps": [{"tool": t, "args": a, "out": dumps(o), "tok": tokens(o)} for t, a, o in steps], "defs_tok": dtok, "instr_tok": itok,
            "all_plastics": sum(tokens(g.node(i)) for i, n in g.nodes.items() if n[2] == "plastics"),
            "all_catalogue": sum(tokens(g.node(i)) for i, n in g.nodes.items() if n[2] == "catalogue"),
            "fam_edges": sum(1 for es in g.out.values() for r, _ in es if r == "has_field"), "fam_own": fam_own,
            "nodes_total": len(g.nodes), "hdpe_brief": tokens(g.node("PLX-VAR-HDPE")), "hdpe_full": tokens(g.node("PLX-VAR-HDPE", detail="full")),
            "series": len(g.series), "obs": sum(g.obs.values()), "series_with_data": sum(1 for v in g.points.values() if v), "bench": bench}


