def main():
    d = json.dumps(data(), ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    uk = (HERE / "demo.template.html").read_text(encoding="utf-8").replace("__DATA__", d)
    (DOCS / "demo.html").write_text(uk, encoding="utf-8")
    ru = uk
    for a, b in RU:
        if a not in ru:
            raise SystemExit(f"translation source not found in template: {a[:70]!r}")
        ru = ru.replace(a, b)
    (DOCS / "demo-ru.html").write_text(ru, encoding="utf-8")
    print("wrote docs/demo.html, docs/demo-ru.html")


if __name__ == "__main__":
    main()
